// the enzymes of each vendor are groups of the enzyme filter of the editor ("Vendor: NEB"); the groups made by the user are
// kept in the browser as before. This runs before the editor is loaded: it reads the groups from this function.
(function () {
  'use strict';
  const PREFIX = 'Vendor: ';
  window.getExistingEnzymeGroups = function () {
    let stored = {};
    try {
      stored = JSON.parse(window.localStorage.getItem('enzymeGroups') || '{}') || {};
    } catch (error) {
      stored = {};
    }
    const groups = {};
    Object.keys(window.EnzymeLibrary.groups).forEach(function (vendor) {
      groups[PREFIX + vendor] = window.EnzymeLibrary.groups[vendor];
    });
    // the vendor groups are not kept in the browser: they come from the library
    Object.keys(stored).forEach(function (name) {
      if (name.indexOf(PREFIX) !== 0) {
        groups[name] = stored[name];
      }
    });
    return groups;
  };
})();
